CREATE DATABASE IF NOT EXISTS lirandzu CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE lirandzu;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role ENUM('admin','provider') NOT NULL DEFAULT 'provider',status ENUM('active','blocked') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,slug VARCHAR(120) NOT NULL UNIQUE,description VARCHAR(500),active BOOLEAN NOT NULL DEFAULT TRUE,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE providers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE NULL,category_id BIGINT UNSIGNED NOT NULL,business_name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,city VARCHAR(100) NOT NULL,description TEXT NOT NULL,indicative_price DECIMAL(12,2),cover_image VARCHAR(500),verified BOOLEAN DEFAULT FALSE,featured BOOLEAN DEFAULT FALSE,status ENUM('pending','active','rejected','suspended') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE provider_applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,applicant_name VARCHAR(140) NOT NULL,business_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(30) NOT NULL,category_id BIGINT UNSIGNED NOT NULL,city VARCHAR(100) NOT NULL,description TEXT NOT NULL,status ENUM('pending','approved','rejected') DEFAULT 'pending',admin_notes VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at TIMESTAMP NULL,FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE service_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_code VARCHAR(32) NOT NULL UNIQUE,provider_id BIGINT UNSIGNED NOT NULL,customer_name VARCHAR(140) NOT NULL,customer_email VARCHAR(190),customer_phone VARCHAR(30) NOT NULL,event_date DATE,event_city VARCHAR(100) NOT NULL,budget DECIMAL(12,2),message TEXT NOT NULL,status ENUM('submitted','forwarded','answered','closed','cancelled') DEFAULT 'forwarded',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(provider_id) REFERENCES providers(id)) ENGINE=InnoDB;
CREATE TABLE request_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED NOT NULL,sender_user_id BIGINT UNSIGNED NULL,sender_role ENUM('customer','provider','admin') NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES service_requests(id) ON DELETE CASCADE,FOREIGN KEY(sender_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
INSERT INTO categories(name,slug,sort_order) VALUES ('Vestidos de noiva','vestidos-de-noiva',1),('Fotografia','fotografia',2),('Decoração','decoracao',3),('Catering','catering',4),('Bolos de casamento','bolos',5),('Música e DJ','musica-dj',6),('Salões e espaços','espacos',7),('Maquilhagem e beleza','beleza',8);
